CREATE TRIGGER mirror_accounts_ins AFTER INSERT ON accounts BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('accounts', NEW."login", ''); END;
CREATE TRIGGER mirror_accounts_upd AFTER UPDATE ON accounts BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('accounts', NEW."login", ''); END;
CREATE TRIGGER mirror_accounts_key AFTER UPDATE ON accounts WHEN OLD."login" IS NOT NEW."login" BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('accounts', OLD."login", ''); END;
CREATE TRIGGER mirror_accounts_del AFTER DELETE ON accounts BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('accounts', OLD."login", ''); END;
INSERT OR IGNORE INTO mirror_state (tbl) VALUES ('accounts');
